const pptxgen = require("pptxgenjs");

const slideConfig = { type: "cover", index: 1, title: "2024 JavaScript Rising Stars" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: theme.accent }
  });

  // Decorative geometric shapes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 0.4, w: 2.2, h: 2.2, fill: { color: theme.secondary }, rotate: 15
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.0, y: 0.8, w: 1.6, h: 1.6, fill: { color: theme.accent, transparency: 60 }, rotate: 30
  });

  // Star icon (text-based)
  slide.addText("\u2605", {
    x: 0.6, y: 0.5, w: 1, h: 1, fontSize: 60, color: theme.accent, fontFace: "Arial"
  });

  // Main title
  slide.addText("2024 JavaScript\nRising Stars", {
    x: 0.6, y: 1.6, w: 7.5, h: 1.8, fontSize: 44, fontFace: "Georgia",
    color: theme.light, bold: true, lineSpacingMultiple: 1.1
  });

  // Subtitle
  slide.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.6, y: 3.4, w: 7, h: 0.5, fontSize: 20, fontFace: "Calibri",
    color: theme.accent
  });

  // Methodology line
  slide.addText("9th Edition  \u00B7  GitHub stars added in 2024  \u00B7  Best of JS curated list", {
    x: 0.6, y: 4.2, w: 7, h: 0.4, fontSize: 13, fontFace: "Calibri",
    color: theme.light, italic: true
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: theme.accent }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "000814", secondary: "001d3d", accent: "ffc300", light: "ffd60a", bg: "003566" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

