const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 3, title: "shadcn/ui Deep Dive" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("shadcn/ui: Copy-Paste Components Win for the Second Year", {
    x: 0.5, y: 0.25, w: 9, h: 0.6, fontSize: 22, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0, fit: "shrink"
  });

  // Left column: Star trajectory
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 3.8, h: 3.6, fill: { color: theme.secondary }, rectRadius: 0
  });

  slide.addText("Star Trajectory", {
    x: 0.7, y: 1.2, w: 3.4, h: 0.4, fontSize: 14, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0
  });

  // Total stars callout
  slide.addText("77.5k", {
    x: 0.7, y: 1.7, w: 3.4, h: 0.8, fontSize: 48, fontFace: "Georgia",
    color: theme.light, bold: true, margin: 0
  });
  slide.addText("total GitHub stars", {
    x: 0.7, y: 2.45, w: 3.4, h: 0.3, fontSize: 12, fontFace: "Calibri",
    color: theme.light, margin: 0
  });

  // Year-over-year bars using chart
  slide.addChart(pres.charts.BAR, [{
    name: "Stars",
    labels: ["2023", "2024"],
    values: [39.5, 38.0]
  }], {
    x: 0.7, y: 2.9, w: 3.4, h: 1.6,
    barDir: "col",
    chartColors: [theme.accent],
    chartArea: { fill: { color: theme.secondary } },
    plotArea: { fill: { color: theme.secondary } },
    catAxisLabelColor: theme.light,
    catAxisLabelFontSize: 10,
    valAxisHidden: true,
    catGridLine: { style: "none" },
    valGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.light,
    dataLabelFontSize: 11,
    showLegend: false
  });

  // Right column: Key 2024 features
  slide.addText("Key 2024 Additions", {
    x: 4.6, y: 1.1, w: 5, h: 0.4, fontSize: 14, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0
  });

  const features = [
    { text: "\u25B8  Charts", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    Powered by Recharts", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg, breakLine: true } },
    { text: "\u25B8  Themes & Blocks", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    CSS variable generation + layout collections", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg, breakLine: true } },
    { text: "\u25B8  Responsive Sidebar", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    New component for adaptive navigation", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg, breakLine: true } },
    { text: "\u25B8  Upgraded CLI", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    Next.js, Remix, Vite, Laravel, monorepos", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg, breakLine: true } },
    { text: "\u25B8  Registry Ecosystem", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    Motion-Primitives, Magic UI", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg, breakLine: true } },
    { text: "\u25B8  Vercel v0 Integration", options: { fontSize: 13, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "    AI-generated component workflows", options: { fontSize: 11, fontFace: "Calibri", color: theme.bg } }
  ];

  slide.addText(features, {
    x: 4.6, y: 1.6, w: 5, h: 3.2, valign: "top", margin: 0, paraSpaceAfter: 2
  });

  // Bottom note
  slide.addText("Created January 2023  \u00B7  Developers own and customize component code", {
    x: 0.5, y: 4.9, w: 8.5, h: 0.3, fontSize: 11, fontFace: "Calibri",
    color: theme.bg, italic: true, margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "000814", secondary: "001d3d", accent: "ffc300", light: "ffd60a", bg: "003566" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

