const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 4, title: "Frontend Frameworks" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("htmx Overtakes React as #1 Front-end Framework by Stars Added", {
    x: 0.5, y: 0.25, w: 9, h: 0.6, fontSize: 22, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0, fit: "shrink"
  });

  // Bar chart
  slide.addChart(pres.charts.BAR, [{
    name: "Stars Added (thousands)",
    labels: ["htmx", "React", "Svelte", "Vue.js", "Angular"],
    values: [16.8, 14.2, 6.1, 5.9, 3.5]
  }], {
    x: 0.5, y: 1.0, w: 5.5, h: 3.8,
    barDir: "col",
    chartColors: [theme.accent],
    chartArea: { fill: { color: theme.primary } },
    plotArea: { fill: { color: theme.primary } },
    catAxisLabelColor: theme.light,
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.bg,
    valAxisLabelFontSize: 9,
    valGridLine: { color: theme.secondary, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.light,
    dataLabelFontSize: 11,
    showLegend: false
  });

  // Key insights - right column
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.0, w: 3.4, h: 1.15, fill: { color: theme.secondary }
  });
  slide.addText([
    { text: "htmx", options: { bold: true, color: theme.accent, fontSize: 13, fontFace: "Georgia", breakLine: true } },
    { text: "Extends HTML with hx-* attributes for server-driven apps. No JavaScript required.", options: { fontSize: 11, fontFace: "Calibri", color: theme.light } }
  ], { x: 6.5, y: 1.05, w: 3.0, h: 1.05, valign: "middle", margin: 0 });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 2.3, w: 3.4, h: 1.15, fill: { color: theme.secondary }
  });
  slide.addText([
    { text: "React 19", options: { bold: true, color: theme.accent, fontSize: 13, fontFace: "Georgia", breakLine: true } },
    { text: "Launched Dec 2024 after 3 years. Server Components, Server Functions, new hooks.", options: { fontSize: 11, fontFace: "Calibri", color: theme.light } }
  ], { x: 6.5, y: 2.35, w: 3.0, h: 1.05, valign: "middle", margin: 0 });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 3.6, w: 3.4, h: 1.15, fill: { color: theme.secondary }
  });
  slide.addText([
    { text: "Svelte 5", options: { bold: true, color: theme.accent, fontSize: 13, fontFace: "Georgia", breakLine: true } },
    { text: "Introduced \"runes\" for explicit reactive state. Highest positive opinion in State of JS.", options: { fontSize: 11, fontFace: "Calibri", color: theme.light } }
  ], { x: 6.5, y: 3.65, w: 3.0, h: 1.05, valign: "middle", margin: 0 });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "000814", secondary: "001d3d", accent: "ffc300", light: "ffd60a", bg: "003566" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

