const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 6, title: "Vue Ecosystem" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Vue Ecosystem Flourishes: Nuxt, PrimeVue, and Slidev Lead Growth", {
    x: 0.5, y: 0.25, w: 9, h: 0.6, fontSize: 22, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0, fit: "shrink"
  });

  // Top 5 cards layout
  const projects = [
    { name: "Nuxt", stars: "+6.2k", desc: "Full-stack Vue framework" },
    { name: "PrimeVue", stars: "+5.4k", desc: "Enterprise UI component library" },
    { name: "Slidev", stars: "+4.7k", desc: "Presentation slides for developers" },
    { name: "shadcn-vue", stars: "+4.1k", desc: "Vue port of shadcn/ui components" },
    { name: "VitePress", stars: "+3.7k", desc: "Vite-powered static site generator" }
  ];

  projects.forEach((p, i) => {
    const x = 0.5 + i * 1.82;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: 1.1, w: 1.7, h: 2.2, fill: { color: theme.secondary }
    });
    slide.addText(String(i + 1), {
      x: x, y: 1.15, w: 1.7, h: 0.5, fontSize: 28, fontFace: "Georgia",
      color: theme.accent, bold: true, align: "center", margin: 0
    });
    slide.addText(p.name, {
      x: x + 0.1, y: 1.7, w: 1.5, h: 0.35, fontSize: 13, fontFace: "Georgia",
      color: theme.light, bold: true, align: "center", margin: 0
    });
    slide.addText(p.stars, {
      x: x, y: 2.1, w: 1.7, h: 0.4, fontSize: 20, fontFace: "Georgia",
      color: theme.accent, bold: true, align: "center", margin: 0
    });
    slide.addText(p.desc, {
      x: x + 0.1, y: 2.55, w: 1.5, h: 0.65, fontSize: 10, fontFace: "Calibri",
      color: theme.light, align: "center", margin: 0
    });
  });

  // Key insights section
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.6, w: 9, h: 1.2, fill: { color: theme.secondary }
  });

  slide.addText([
    { text: "Vue 3.5 Reactivity Rework  ", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: theme.accent } },
    { text: "The lighter alien-signals approach has already landed in the main branch, delivering significant performance gains.", options: { fontSize: 12, fontFace: "Calibri", color: theme.light, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "Ecosystem Confidence  ", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: theme.accent } },
    { text: "The flourishing of high-quality UI libraries (PrimeVue, shadcn-vue) signals a maturing, confident Vue ecosystem.", options: { fontSize: 12, fontFace: "Calibri", color: theme.light } }
  ], { x: 0.7, y: 3.7, w: 8.6, h: 1.0, valign: "top", margin: 0 });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "000814", secondary: "001d3d", accent: "ffc300", light: "ffd60a", bg: "003566" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

