    { num: "1", title: "Component ownership beats imports", body: "shadcn/ui\u2019s copy-paste model proved its staying power for a second year, reaching 77.5k total stars." },
    { num: "2", title: "HTML-first is serious", body: "htmx overtook React as the #1 front-end framework by stars added, validating server-driven architectures." },
    { num: "3", title: "React is becoming a framework spec", body: "Server Components and Server Functions make React more of a specification than a standalone library." },
    { num: "4", title: "AI integration is table stakes", body: "4 of the top 10 overall projects (n8n, Flowise, Supabase, AFFiNE) have significant AI capabilities." },
    { num: "5", title: "Vue\u2019s ecosystem maturity", body: "A wave of high-quality UI libraries and the Vue 3.5 reactivity overhaul signal a confident ecosystem." }
  ];

  takeaways.forEach((t, i) => {
    const y = 1.05 + i * 0.72;
    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.05, w: 0.38, h: 0.38, fill: { color: theme.accent }
    });
    slide.addText(t.num, {
      x: 0.5, y: y + 0.05, w: 0.38, h: 0.38, fontSize: 14, fontFace: "Arial",
      color: theme.primary, bold: true, align: "center", valign: "middle"
    });
    // Title and body
    slide.addText(t.title, {
      x: 1.05, y: y, w: 8.5, h: 0.3, fontSize: 14, fontFace: "Georgia",
      color: theme.light, bold: true, margin: 0
    });
    slide.addText(t.body, {
      x: 1.05, y: y + 0.3, w: 8.5, h: 0.35, fontSize: 11, fontFace: "Calibri",
      color: theme.bg, margin: 0
    });
  });

  // Forward-looking callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.65, w: 9, h: 0.55, fill: { color: theme.secondary }
  });
  slide.addText([
    { text: "Watch in 2025:  ", options: { bold: true, fontSize: 12, fontFace: "Georgia", color: theme.accent } },
    { text: "Framework convergence  \u00B7  AI-native tooling  \u00B7  The ownership model spreading beyond components", options: { fontSize: 12, fontFace: "Calibri", color: theme.light } }
  ], { x: 0.7, y: 4.65, w: 8.6, h: 0.55, valign: "middle", margin: 0 });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
